function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2); }
function money(value: number, currency: string) { return new Intl.NumberFormat(undefined, { style: "currency", currency: currency || "SAR", maximumFractionDigits: 2 }).format(Number.isFinite(value) ? value : 0); }

function ExpenseTrendChart({ trend }: { trend: { months: string[]; series: { currency: string; points: { month: string; totalAmount: number; claimCount: number }[] }[] } }) {
  if (!trend.series.length) return <div className="admin-feedback">No Travel Expense claims are available for the last six months.</div>;
  return <div className="grid gap-4 lg:grid-cols-2">{trend.series.map((series, index) => {
    const max = Math.max(1, ...series.points.map(point => point.totalAmount));
    const coords = series.points.map((point, pointIndex) => `${series.points.length === 1 ? 50 : (pointIndex / (series.points.length - 1)) * 100},${94 - (point.totalAmount / max) * 84}`).join(" ");
    const latest = series.points.at(-1)!;
    const prior = series.points.at(-2)?.totalAmount ?? 0;
    const change = latest.totalAmount - prior;
    const tone = ["#60a5fa", "#34d399", "#fbbf24", "#c084fc"][index % 4];
    return <div className="rounded-md border border-blue-500/20 bg-slate-950/20 p-3" key={series.currency}><div className="mb-2 flex items-center justify-between gap-3"><div><strong>{series.currency}</strong><p className="muted text-xs">{money(latest.totalAmount, series.currency)} this month · {latest.claimCount} claim{latest.claimCount === 1 ? "" : "s"}</p></div><Badge variant="outline" className={change > 0 ? "border-amber-400/50 text-amber-200" : change < 0 ? "border-emerald-400/50 text-emerald-200" : ""}>{change === 0 ? "No change" : `${change > 0 ? "+" : ""}${money(change, series.currency)}`}</Badge></div><svg viewBox="0 0 100 100" className="h-24 w-full" role="img" aria-label={`${series.currency} monthly Travel Expense trend`} preserveAspectRatio="none"><line x1="0" y1="94" x2="100" y2="94" stroke="#31507a" strokeWidth="1"/><polyline fill="none" stroke={tone} strokeWidth="3" vectorEffect="non-scaling-stroke" points={coords}/>{series.points.map((point, pointIndex) => <circle key={point.month} cx={series.points.length === 1 ? 50 : (pointIndex / (series.points.length - 1)) * 100} cy={94 - (point.totalAmount / max) * 84} r="3" fill={tone}><title>{`${point.month}: ${money(point.totalAmount, series.currency)} across ${point.claimCount} claim${point.claimCount === 1 ? "" : "s"}`}</title></circle>)}</svg><div className="mt-1 grid grid-cols-6 gap-1 text-center text-[10px] text-slate-400">{trend.months.map(month => <span key={month}>{month.slice(5)}</span>)}</div></div>;
  })}</div>;
}

